package com.gomgomapps.math.core;
import java.util.*;import java.io.*;import org.junit.Test;import static org.junit.Assert.*;
public class ContextEstimateCheckTest {
 private ContextEstimateCheck.Status checked(Question q,String proposal,int unit,String verdict){var p=ContextEstimateCheck.plan(q,proposal,unit);return ContextEstimateCheck.check(q,proposal,unit,""+p.roundedFirst(),""+p.roundedSecond(),p.estimate().toString(),p.difference().toString(),verdict);}
 @Test public void publicAllOperationsAndWithinNeverCertifiesExact(){for(int op=0;op<4;op++){Question q=ContextCalculationMethods.make(op,op==2?45543:455434,7);String answer=q.answers[0];q.expression="poison";q.answers=new String[]{"poison"};assertEquals(ContextEstimateCheck.Status.WITHIN,checked(q,answer,1000,"within"));assertEquals(ContextEstimateCheck.Status.WRONG_COMPARISON,checked(q,answer,1000,"outside"));}Question q=ContextCalculationMethods.make(3,455434,7);var p=ContextEstimateCheck.plan(q,"65062",1000);assertEquals(Rational.of(65000),p.estimate());assertEquals(Rational.of(500,7),p.tolerance());assertEquals(Rational.of(62),p.difference());assertEquals(ContextEstimateCheck.Status.WITHIN,checked(q,"65000",1000,"within"));assertFalse(new Checker().check(q,List.of(),List.of("65000")).correct());assertEquals(ContextEstimateCheck.Status.OUTSIDE,checked(q,"1",1000,"outside"));}
 @Test public void eachLearnerStepAndZeroFractionBoundaries(){Question q=ContextCalculationMethods.make(0,155,255);var p=ContextEstimateCheck.plan(q,"410",100);assertEquals(ContextEstimateCheck.Status.WRONG_FIRST,ContextEstimateCheck.check(q,"410",100,"100","300","500","90","within"));assertEquals(ContextEstimateCheck.Status.WRONG_SECOND,ContextEstimateCheck.check(q,"410",100,"200","200","500","90","within"));assertEquals(ContextEstimateCheck.Status.WRONG_ESTIMATE,ContextEstimateCheck.check(q,"410",100,"200","300","499","90","within"));assertEquals(ContextEstimateCheck.Status.WRONG_DIFFERENCE,ContextEstimateCheck.check(q,"410",100,"200","300","500","91","within"));assertEquals(ContextEstimateCheck.Status.WITHIN,checked(q,"410",100,"within"));Question frac=ContextCalculationMethods.make(3,33,3);assertEquals(Rational.of(50,3),ContextEstimateCheck.plan(frac,"11",100).tolerance());assertEquals(ContextEstimateCheck.Status.WITHIN,checked(frac,"11",100,"within"));Question zero=ContextCalculationMethods.make(2,1000000,0);assertEquals(ContextEstimateCheck.Status.WITHIN,checked(zero,"0",1000000,"within"));assertEquals(ContextEstimateCheck.Status.OUTSIDE,checked(zero,"1",1000000,"outside"));assertNull(ContextEstimateCheck.plan(q,"1000001",100));assertNull(ContextEstimateCheck.plan(q,"410",1));assertEquals(ContextEstimateCheck.Status.INPUT_NEEDED,ContextEstimateCheck.check(q,"410",100,"1/0","300","500","90","within"));}
 @Test public void exactAnswersAlwaysFitConservativeEnvelope(){for(int op=0;op<4;op++)for(int a=0;a<=100;a++)for(int b=0;b<=20;b++){if(op==1&&a<b||op==3&&(b==0||a%b!=0))continue;Question q=ContextCalculationMethods.make(op,a,b);for(int unit:ContextEstimateCheck.UNITS)assertEquals(ContextEstimateCheck.Status.WITHIN,checked(q,q.answers[0],unit,"within"));}}
 @Test public void serializedDraftKeepsIdentityInverseAndMain()throws Exception{Question q=ContextCalculationMethods.make(3,455434,7);String signature=q.signature();q.inverseProposal="1";q.inverseValue="7";q.inverseChecked=true;q.estimateProposal="1";q.estimateUnit=1000;q.estimateFirst="455000";q.estimateValue="65000";q.estimateDifference="64999";q.estimateVerdict="outside";q.estimateChecked=true;ByteArrayOutputStream b=new ByteArrayOutputStream();new ObjectOutputStream(b).writeObject(q);Question copy=(Question)new ObjectInputStream(new ByteArrayInputStream(b.toByteArray())).readObject();assertEquals(signature,copy.signature());assertEquals("7",copy.inverseValue);assertTrue(copy.inverseChecked);assertEquals(ContextEstimateCheck.Status.OUTSIDE,ContextEstimateCheck.check(copy,copy.estimateProposal,copy.estimateUnit,copy.estimateFirst,copy.estimateSecond,copy.estimateValue,copy.estimateDifference,copy.estimateVerdict));assertEquals("65062",copy.answers[0]);}
}
